-- Idempotent Canonical Database Seed
-- Muscle Intelligence — Cross-Platform Scientific Data Foundation
-- Contains complete canonical definitions for Rounds 1 - 26, 28 functional muscles, and research studies.

-- 1. Source Licenses
ON CONFLICT (id) DO UPDATE SET
    full_name = EXCLUDED.full_name,
    is_commercial_allowed = EXCLUDED.is_commercial_allowed,
    requires_share_alike = EXCLUDED.requires_share_alike;

-- 2. External Sources
ON CONFLICT (id) DO UPDATE SET
    license_id = EXCLUDED.license_id,
    name = EXCLUDED.name,
    url = EXCLUDED.url;

-- 3. Muscle Groups (10 Primary Anatomical Regions)
ON CONFLICT (id) DO UPDATE SET
    name = EXCLUDED.name,
    description = EXCLUDED.description,
    display_order = EXCLUDED.display_order;

-- 4. Muscles (28 Functional Units and Complexes)
ON CONFLICT (id) DO UPDATE SET
    name = EXCLUDED.name,
    description = EXCLUDED.description,
    default_weekly_target_min = EXCLUDED.default_weekly_target_min,
    default_weekly_target_max = EXCLUDED.default_weekly_target_max;

-- 5. Movement Patterns
ON CONFLICT (id) DO UPDATE SET
    name = EXCLUDED.name,
    description = EXCLUDED.description;

-- 6. Equipment
ON CONFLICT (id) DO UPDATE SET
    name = EXCLUDED.name,
    description = EXCLUDED.description;

-- 7. Model Versions & Parameters
     'Exposure(m) = sum(hard_sets(e) * coefficient(e, m))',
     'Exposure(m) = \sum_{e} \left[ \text{hard\_sets}(e) \times \text{coefficient}(e, m) \right]',
     'Fractional volume bookkeeping derived from Schoenfeld et al. (2017) and Pelland et al. (2026) dose-response relationships.'),
    ('joint_torque_v1.0', 'Static Peak Joint Torque Estimator', 'biomechanics', '1.0.0',
     'tau = F * r * sin(theta)',
     '\tau = F \times r \times \sin(\theta)',
     'Standard Newtonian mechanics using bodyweight segment mass fractions from Dempster (1955) and moment arms.'),
    ('work_power_v1.0', 'Mechanical Work and Power Model', 'biomechanics', '1.0.0',
     'W = F * d * cos(theta), P = W / t',
     'W = F \times d \times \cos(\theta), \quad P = \frac{W}{\Delta t}',
     'Classical work-energy theorem applied to center-of-mass vertical displacement during calisthenics.'),
    ('rir_estimator_v1.0', 'Repetitions In Reserve Deductive Estimator', 'fatigue', '1.0.0',
     'RIR = max_sound_reps - completed_reps',
     '\text{RIR} = \text{reps}_{\text{max\_sound}} - \text{reps}_{\text{completed}}',
     'Zourdos et al. (2016) resistance training RPE/RIR scale calibrated for bodyweight failure thresholds.')
ON CONFLICT (id) DO UPDATE SET
    formula_definition = EXCLUDED.formula_definition,
    latex_representation = EXCLUDED.latex_representation;

ON CONFLICT (model_version_id, parameter_key) DO UPDATE SET
    parameter_value = EXCLUDED.parameter_value;

-- 8. Canonical Exercises (All Rounds 1 - 26)
ON CONFLICT (id) DO UPDATE SET
    name = EXCLUDED.name,
    instructions = EXCLUDED.instructions,
    safety_cautions = EXCLUDED.safety_cautions;

-- 9. Exercise-to-Muscle Mappings with Scientific Evidence
ON CONFLICT (exercise_id, muscle_id, muscle_head_id) DO UPDATE SET
    role = EXCLUDED.role,
    coefficient = EXCLUDED.coefficient,
    joint_action = EXCLUDED.joint_action,
    evidence_category = EXCLUDED.evidence_category,
    confidence = EXCLUDED.confidence;

-- 10. Canonical Round Templates (Rounds 1 - 26)
ON CONFLICT (id) DO UPDATE SET
    name = EXCLUDED.name,
    description = EXCLUDED.description;

-- 11. Round Exercises (Structured Slots)
ON CONFLICT (round_template_id, sequence) DO UPDATE SET
    exercise_id = EXCLUDED.exercise_id,
    default_value = EXCLUDED.default_value;

-- 12. Landmark Peer-Reviewed Research Studies
     'Surface electromyographic activation of the latissimus dorsi and other muscles during the pull-up and chin-up exercises',
     ARRAY['Youdas JW', 'Amundson CL', 'Cicero KS', 'Hahn JJ', 'Harkness JR', 'Hollman JH'],
     2010, 'Journal of Strength and Conditioning Research',
     'Investigated surface electromyographic activity in latissimus dorsi, biceps brachii, lower trapezius, and infraspinatus across pronated pull-up and supinated chin-up variations.',
     'cross_sectional_emg', 'emg_excitation_evidence', TRUE),
    ('a0000000-0000-0000-0000-000000000002', 'pubmed', '10.1519/R-16074.1', '16095405',
     'Comparison of muscle activation using various hand positions during the push-up exercise',
     ARRAY['Cogley RM', 'Archambault TA', 'Fibeger VD', 'Koverman JW'],
     2005, 'Journal of Strength and Conditioning Research',
     'Evaluated wide, shoulder-width, and narrow/diamond hand placements during push-ups. Narrow diamond position elicited significantly greater EMG amplitude in triceps brachii and sternal pectoralis.',
     'cross_sectional_emg', 'emg_excitation_evidence', TRUE),
    ('a0000000-0000-0000-0000-000000000003', 'pubmed', '10.1519/JSC.0b013e31820f50be', '21873902',
     'Electromyographic and kinetic analysis of variations of the push-up exercise',
     ARRAY['Ebben WP', 'Wurm B', 'VanderZanden TL', 'Spadavecchia ML', 'Duchow AR', 'Feldmann CR'],
     2011, 'Journal of Strength and Conditioning Research',
     'Measured ground reaction force and sEMG across standard, incline, decline, knee-supported, and elevated push-up variations.',
     'biomechanical_simulation', 'biomechanical_evidence', TRUE),
    ('a0000000-0000-0000-0000-000000000004', 'pubmed', '10.1007/s40279-017-0779-8', '28834797',
     'Greater Electromyographic Responses Do Not Imply Greater Motor Unit Recruitment and Cannot Be Used to Predict Hypertrophy',
     ARRAY['Vigotsky AD', 'Halperin I', 'Lehman GJ', 'Trajano GS', 'Vieira TM'],
     2018, 'Sports Medicine',
     'Critical review establishing methodological limitations of surface EMG, warning that surface EMG amplitude cannot directly predict motor unit force or long-term longitudinal hypertrophy.',
     'systematic_review', 'emg_excitation_evidence', TRUE)
ON CONFLICT (doi) DO UPDATE SET
    title = EXCLUDED.title,
    abstract = EXCLUDED.abstract;

-- 13. Link evidence to exercise_muscles
SELECT em.id, 'a0000000-0000-0000-0000-000000000001'::uuid, 'agonist', 0.95, 'Youdas 2010 confirms latissimus dorsi is primary agonist (>115% MVC) in pronated pull-up.'
FROM public.exercise_muscles em
WHERE em.exercise_id = 'pullup_standard' AND em.muscle_id = 'latissimus_dorsi'
ON CONFLICT (exercise_muscle_id, study_id) DO NOTHING;
